    #[test]
    fn the_activity_row_speaks_the_interface_language() {
        let dir = std::env::temp_dir().join(format!("sortlens-ui-activity-i18n-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let root = dir.join("photos");
        std::fs::create_dir_all(&root).expect("root");
        let fixture = sortlens_testkit::Fixture::new("ui-activity-i18n");
        std::fs::copy(fixture.jpeg("IMG_0001.jpg", [30, 60, 140], 64, 48), root.join("IMG_0001.jpg")).expect("copy");
        let mut engine = Engine::open(&dir).expect("open");
        engine.begin_scan(root.to_string_lossy().to_string()).expect("scan");
        for _ in 0..600 {
            if engine.poll().is_some() {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
        let job = engine
            .jobs()
            .into_iter()
            .find(|job| job.kind == sortlens_engine::JobKind::Scan)
            .expect("the scan is in the activity stack");
        assert_eq!(job.status, sortlens_engine::JobStatus::Done);
        assert_eq!(
            job.detail_kind(),
            sortlens_engine::JobDetail::Finished {
                files: 1,
                dirs: 1,
                unreadable: None
            }
        );
        assert_eq!(job_detail(&job), job.detail());
        assert_eq!(job_detail(&job), "1 files · 1 folders");

        let ctx = egui::Context::default();
        let tokens = Tokens::CHARCOAL;
        let mut state = UiState::new(ThemeKind::Midnight, 0.0);
        state.right_tab = RightTab::Activity;
        let paint = |ctx: &egui::Context, state: &mut UiState, engine: &mut Engine| {
            let mut settled = None;
            for _ in 0..2 {
                let mut out = ctx.run_ui(
                    egui::RawInput {
                        screen_rect: Some(Rect::from_min_size(pos2(0.0, 0.0), vec2(360.0, 600.0))),
                        ..egui::RawInput::default()
                    },
                    |ctx| {
                        egui::CentralPanel::default().show(ctx, |ui| {
                            right_panel(ui, state, &tokens, engine);
                        });
                    },
                );
                out.textures_delta.clear();
                settled = Some(out);
            }
            settled.expect("two frames were painted")
        };

        // English first: the words the row has always painted, joined from the piece.
        let english = paint(&ctx, &mut state, &mut engine);
        assert!(label_at(&english, "Scan").is_some(), "the kind paints");
        assert!(label_at(&english, "done").is_some(), "and the state");
        assert!(label_at(&english, "1 files · 1 folders").is_some(), "and the counters");

        // Japanese: the kind, the state and the counters are the catalogue's.
        crate::i18n::set_current(crate::i18n::from_code("ja").expect("Japanese is offered"));
        assert_eq!(job_detail(&job), "1 ファイル · 1 フォルダー");
        let japanese = paint(&ctx, &mut state, &mut engine);
        assert!(label_at(&japanese, "スキャン").is_some(), "the kind is the catalogue's");
        assert!(label_at(&japanese, "完了").is_some(), "and the state");
        assert!(label_at(&japanese, "1 ファイル · 1 フォルダー").is_some(), "and the counters");
        assert!(label_at(&japanese, "Scan").is_none(), "no English kind behind it");
        assert!(label_at(&japanese, "done").is_none(), "no English state behind it");
        assert!(
            label_at(&japanese, "1 files · 1 folders").is_none(),
            "no English counters behind it"
        );

        // Arabic: the same pieces, with the counts in Arabic-Indic digits.
        crate::i18n::set_current(crate::i18n::from_code("ar").expect("Arabic is offered"));
        let arabic = job_detail(&job);
        assert!(arabic.contains('١') && !arabic.contains("files"), "{arabic}");
        let arabic_frame = paint(&ctx, &mut state, &mut engine);
        assert!(label_at(&arabic_frame, "فحص").is_some(), "the kind is the catalogue's");
        assert!(label_at(&arabic_frame, "منتهٍ").is_some(), "and the state");
        assert!(label_at(&arabic_frame, "Scan").is_none(), "no English kind behind it");

        crate::i18n::set_current(crate::i18n::from_code("en").expect("English is offered"));
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// Paint only the bottom bar and hand back what it drew.
    ///
    /// The bar is the whole subject here: a scene that painted the grid too would make "which glyph did I
    /// click" a question about the canvas.
    fn paint_bar(
        ctx: &egui::Context,
        screen: Vec2,
        state: &mut UiState,
        engine: &mut Engine,
        actions: &mut Vec<Action>,
    ) -> egui::FullOutput {
        let input = egui::RawInput {
            screen_rect: Some(Rect::from_min_size(pos2(0.0, 0.0), screen)),
            ..egui::RawInput::default()
        };
        // Twice: the SVG loader is asynchronous, so the first frame lays the bar out and the second
        // paints its glyphs. A single frame would read as "no icons" for a bar full of them.
        let mut settled = None;
        for _ in 0..2 {
            let mut output = ctx.run_ui(input.clone(), |ctx| {
                egui::CentralPanel::default().show(ctx, |ui| {
                    bottom_bar(ui, state, &Tokens::CHARCOAL, engine, actions);
                });
            });
            output.textures_delta.clear();
            settled = Some(output);
        }
        settled.expect("two frames were painted")
    }

    /// The icon-only buttons inside `area`, left to right.
    fn glyphs_in(output: &egui::FullOutput, area: Rect) -> Vec<Rect> {
        let mut rects: Vec<Rect> = output
            .shapes
            .iter()
            .filter_map(|clipped| match &clipped.shape {
                egui::Shape::Mesh(mesh) => Some(mesh.calc_bounds()),
                egui::Shape::Rect(shape) => shape
                    .brush
                    .as_ref()
                    .filter(|brush| brush.fill_texture_id != egui::TextureId::default())
                    .map(|_| shape.rect),
                _ => None,
            })
            .filter(|rect| area.contains(rect.center()))
            .collect();
        rects.sort_by(|left, right| left.center().x.total_cmp(&right.center().x));
        rects
    }

    /// The annotation group's own surface: the one bar-coloured frame narrower than the bar.
    fn pill_in(output: &egui::FullOutput, tokens: &Tokens, screen: Vec2) -> Rect {
        output
            .shapes
            .iter()
            .find_map(|clipped| match &clipped.shape {
                egui::Shape::Rect(shape)
                    if shape.fill == tokens.chrome
                        && shape.rect.width() < screen.x * 0.6
                        && shape.rect.height() < tokens.bottom_bar_h
                        && shape.rect.center().y > screen.y - tokens.bottom_bar_h =>
                {
                    Some(shape.rect)
                }
                _ => None,
            })
            .expect("the annotation group has a surface of its own")
    }

    /// Phase 3B.4 from the window: the centre pill rates and flags the selection, and clicking the star that
    /// is already set clears it. Driven by real clicks on the painted glyphs, because a control that is only
    /// reachable from a keyboard is not the control the bar claims to be.
    #[test]
    fn the_annotation_pill_rates_and_flags_the_selection() {
        let dir = std::env::temp_dir().join(format!("sortlens-ui-pill-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let root = dir.join("photos");
        std::fs::create_dir_all(&root).expect("root");
        let fixture = sortlens_testkit::Fixture::new("ui-pill");
        for index in 1..=2 {
            let name = format!("IMG_000{index}.jpg");
            std::fs::copy(fixture.jpeg(&name, [30 * index as u8, 90, 170], 64, 48), root.join(&name)).expect("copy");
        }
        let mut engine = Engine::open(&dir).expect("open");
        engine.begin_scan(root.to_string_lossy().to_string()).expect("scan");
        for _ in 0..600 {
            if engine.poll().is_some() {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
        let ids: Vec<PhotoId> = engine
            .page(&Filter::default(), Sort::Natural, 0, 10)
            .photos
            .iter()
            .map(|photo| photo.id)
            .collect();
        assert_eq!(ids.len(), 2);
        let (first, second) = (ids[0], ids[1]);

        let ctx = egui::Context::default();
        let screen = vec2(1280.0, 300.0);
        let tokens = Tokens::CHARCOAL;
        let mut state = UiState::new(ThemeKind::Charcoal, 0.0);
        state.selection.select_many(&ids);
        let mut actions: Vec<Action> = Vec::new();
        // The shell installs this on every frame it owns; painting the bar on its own has to say it.
        crate::icons::install(&ctx);

        let output = paint_bar(&ctx, screen, &mut state, &mut engine, &mut actions);
        assert!(actions.is_empty(), "painting presses nothing");
        assert!(
            label_at(&output, "2 selected").is_some(),
            "the pill's count is the selection, in words"
        );
        let pill = pill_in(&output, &tokens, screen);
        let glyphs = glyphs_in(&output, pill);
        assert_eq!(
            glyphs.len(),
            8,
            "five stars and three flags, and nothing else in the pill: {}",
            glyphs.len()
        );

        // A keyword count joins the pill when the primary carries keywords: the bar answers "did it land"
        // without a trip to the Tags panel.
        engine.set_tag(&[first], "sea", true).expect("tag");
        let tagged = paint_bar(&ctx, screen, &mut state, &mut engine, &mut actions);
        assert_eq!(
            glyphs_in(&tagged, pill_in(&tagged, &tokens, screen)).len(),
            9,
            "the tag glyph joins the five stars and three flags"
        );

        // The third star rates both photographs: the pill acts on the selection, like the number keys.
        click_frames(&ctx, screen, glyphs[2].center(), &mut state, &mut engine, &mut actions);
        assert_eq!(engine.photo(first).expect("photo").rating, 3, "three stars on the primary");
        assert_eq!(engine.photo(second).expect("photo").rating, 3, "and on the rest of the selection");
        assert_eq!(
            state.live_notice().map(|(text, _)| text.to_string()),
            Some("Rated 3★ on 2 photos".to_string())
        );

        // The same star again clears it, which is what a star that is already lit should do.
        let output = paint_bar(&ctx, screen, &mut state, &mut engine, &mut actions);
        let glyphs = glyphs_in(&output, pill_in(&output, &tokens, screen));
        click_frames(&ctx, screen, glyphs[2].center(), &mut state, &mut engine, &mut actions);
        assert_eq!(engine.photo(first).expect("photo").rating, 0, "the lit star clears the rating");
        assert_eq!(engine.photo(second).expect("photo").rating, 0);

        // Pick sits after the five stars, and flags the whole selection.
        click_frames(&ctx, screen, glyphs[5].center(), &mut state, &mut engine, &mut actions);
        assert_eq!(engine.photo(first).expect("photo").flag, Flag::Pick);
        assert_eq!(engine.photo(second).expect("photo").flag, Flag::Pick);
        assert_eq!(
            state.live_notice().map(|(text, _)| text.to_string()),
            Some("Picked 2 photos".to_string())
        );

        // And Reject is the seventh glyph: the pill offers all three flag states, not only the happy one.
        let output = paint_bar(&ctx, screen, &mut state, &mut engine, &mut actions);
        let glyphs = glyphs_in(&output, pill_in(&output, &tokens, screen));
        click_frames(&ctx, screen, glyphs[7].center(), &mut state, &mut engine, &mut actions);
        assert_eq!(engine.photo(first).expect("photo").flag, Flag::Reject);
        assert_eq!(engine.photo(second).expect("photo").flag, Flag::Reject);

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// The search field's hint is chosen to fit, because egui clips it hard at the field's edge.
    ///
    /// The field is a fixed 240 points, so the sentence that teaches ⌘K is the one that gets cut on a
    /// display whose font resolves a little wider. The chain is longest first, and the fallback is the
    /// shortest, so a narrow field degrades to a word rather than to half a symbol.
    #[test]
    fn the_search_hint_shrinks_instead_of_being_cut() {
        let width = |text: &str| text.chars().count() as f32 * 7.0;
        let hints = ["Search photos or Ctrl+K", "Search photos", "Search"];
        assert_eq!(
            fitting_hint(&hints, width, 200.0),
            "Search photos or Ctrl+K",
            "a roomy field teaches the key"
        );
        assert_eq!(fitting_hint(&hints, width, 100.0), "Search photos", "a narrow field drops the key");
        assert_eq!(
            fitting_hint(&hints, width, 20.0),
            "Search",
            "a field too narrow for a phrase still says what it is"
        );
    }

    /// The message about the last action belongs to the bar, but it is not laid out in it.
    ///
    /// It used to be, in the points the selection pill and the size slider leave: on a 1280-point window
    /// that is a few dozen, and truncating the sentence by characters did not bound it by pixels, so
    /// "Selected 7 photos" painted straight through the pill's own "7 selected". A toast above the bar
    /// has the room a sentence needs at every width, and the bar keeps each control where it was — so
    /// the assertion is geometric, at the widths where the bar is fullest.
    #[test]
    fn the_notice_floats_above_the_bar_rather_than_through_the_selection_count() {
        let dir = std::env::temp_dir().join(format!("sortlens-ui-notice-toast-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let mut engine = Engine::open(&dir).expect("open");
        let root = dir.join("photos");
        std::fs::create_dir_all(&root).expect("root");
        let fixture = sortlens_testkit::Fixture::new("ui-notice-toast");
        for name in ["a.jpg", "b.jpg"] {
            std::fs::copy(fixture.jpeg(name, [90, 120, 200], 64, 64), root.join(name)).expect("copy");
        }
        engine.begin_scan(root.to_string_lossy().to_string()).expect("scan");
        for _ in 0..600 {
            if engine.poll().is_some() {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
        assert_eq!(engine.stats().total, 2, "the bar needs a selection to count");
        let mut thumbs = Thumbnails::new(dir.join("cache"));
        let tokens = Tokens::CHARCOAL;

        for width in [1280.0_f32, 1024.0, 900.0] {
            let screen = vec2(width, 800.0);
            let mut state = UiState::new(ThemeKind::Charcoal, 0.0);
            let ids: Vec<_> = engine
                .page(&state.filter(), state.sort, 0, 100)
                .photos
                .iter()
                .map(|photo| photo.id)
                .collect();
            state.selection.select_many(&ids);
            state.notice("Selected 2 photos");
            let ctx = egui::Context::default();
            crate::theme::apply(&ctx, ThemeKind::Charcoal);
            crate::icons::install(&ctx);
            let mut settled = None;
            // Twice: an area that has not been laid out yet places itself from its own bounds, and only
            // the second frame knows the size the sentence took.
            for _ in 0..2 {
                let mut output = ctx.run_ui(
                    egui::RawInput {
                        screen_rect: Some(Rect::from_min_size(pos2(0.0, 0.0), screen)),
                        ..egui::RawInput::default()
                    },
                    |ctx| {
                        egui::CentralPanel::default().show(ctx, |ui| {
                            let _ = show(ui, &mut state, &mut engine, &mut thumbs);
                        });
                    },
                );
                output.textures_delta.clear();
                settled = Some(output);
            }
            let output = settled.expect("two frames were painted");
            let toast = label_at(&output, "Selected 2 photos")
                .unwrap_or_else(|| panic!("at {width} points the bar paints no message for the action"));
            let bar_top = screen.y - tokens.bottom_bar_h;
            assert!(
                toast.bottom() <= bar_top,
                "at {width} points the message ({toast:?}) reaches into the bar, whose top is {bar_top}"
            );
            assert!(
                toast.min.x >= 0.0 && toast.max.x <= width,
                "at {width} points the message ({toast:?}) runs off the window"
            );
            // The count is still the bar's own answer, and still painted: the message did not take its
            // place, it moved off the row they were fighting over.
            assert!(
                label_at(&output, "2 selected").is_some(),
                "at {width} points the pill still counts the selection"
            );
        }

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// The detail view's own rows are its fixed cost, and the photograph yields exactly that much.
    ///
    /// They were budgeted at a guessed 118 points once, and the real rows — facts, P/X/U row,
    /// keywords, suggestions, histogram with its lookahead, key hint — always outgrew it, so the
    /// filmstrip sat under the bottom bar at every window size, the workspace's own baseline
    /// included. The last row is the one asserted: if the key hint is wholly on screen, everything
    /// above it is too.
    #[test]
    fn the_detail_view_keeps_its_last_row_above_the_bar_at_every_size() {
        let dir = std::env::temp_dir().join(format!("sortlens-ui-detail-footer-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let mut engine = Engine::open(&dir).expect("open");
        let root = dir.join("photos");
        std::fs::create_dir_all(&root).expect("root");
        let fixture = sortlens_testkit::Fixture::new("ui-detail-footer");
        for name in ["a.jpg", "b.jpg", "c.jpg"] {
            std::fs::copy(fixture.jpeg(name, [90, 120, 200], 64, 64), root.join(name)).expect("copy");
        }
        engine.begin_scan(root.to_string_lossy().to_string()).expect("scan");
        for _ in 0..600 {
            if engine.poll().is_some() {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
        let ids: Vec<_> = engine
            .page(&Filter::default(), Sort::default(), 0, 100)
            .photos
            .iter()
            .map(|photo| photo.id)
            .collect();
        assert_eq!(ids.len(), 3, "three photographs, so the lookahead has neighbours");
        // A keyword is one more row above the filmstrip: the footer the guess got wrong-most.
        engine.set_tag(&[ids[1]], "sea", true).expect("tag");
        let mut thumbs = Thumbnails::new(dir.join("cache"));
        let tokens = Tokens::CHARCOAL;
        let hint = "P/X/U flag · 1–5 rate · left/right walk · Z zoom · Esc close";

        for (width, height) in [(1440.0_f32, 900.0_f32), (1280.0, 800.0), (1100.0, 700.0)] {
            let screen = vec2(width, height);
            let mut state = UiState::new(ThemeKind::Charcoal, 0.0);
            state.view = View::Detail;
            state.selection.replace(ids[1]);
            let ctx = egui::Context::default();
            crate::theme::apply(&ctx, ThemeKind::Charcoal);
            crate::icons::install(&ctx);
            let mut settled = None;
            // Twice: the footer is measured on the frame it paints, so the first frame still
            // reserves the old estimate.
            for _ in 0..2 {
                let mut output = ctx.run_ui(
                    egui::RawInput {
                        screen_rect: Some(Rect::from_min_size(pos2(0.0, 0.0), screen)),
                        ..egui::RawInput::default()
                    },
                    |ctx| {
                        egui::CentralPanel::default().show(ctx, |ui| {
                            let _ = show(ui, &mut state, &mut engine, &mut thumbs);
                        });
                    },
                );
                output.textures_delta.clear();
                settled = Some(output);
            }
            let output = settled.expect("two frames were painted");
            let (rect, clip) =
                label_at_clip(&output, hint).unwrap_or_else(|| panic!("at {width}×{height} the view paints no key hint at all"));
            let visible = clip.intersect(rect);
            assert!(
                visible.height() >= rect.height() - 0.5,
                "at {width}×{height} the hint row is cut: {rect:?} inside {clip:?}"
            );
            assert!(
                rect.bottom() <= height - tokens.bottom_bar_h,
                "at {width}×{height} the hint row ({rect:?}) reaches into the bar"
            );
        }

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// A compare's two names and its position share the row with the button cluster, and the names
    /// must end where the buttons begin: laid out the other way round, "2 of 7" was painted under
    /// the Close button and read as a stray "2" between the two file names.
    #[test]
    fn a_compares_names_stop_where_its_buttons_start() {
        let dir = std::env::temp_dir().join(format!("sortlens-ui-compare-header-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let mut engine = Engine::open(&dir).expect("open");
        let root = dir.join("photos");
        std::fs::create_dir_all(&root).expect("root");
        let fixture = sortlens_testkit::Fixture::new("ui-compare-header");
        let names = [
            "2025-11-24_studio_portrait_edinburgh_0004.jpg",
            "2025-11-24_studio_portrait_edinburgh_0005.jpg",
            "2025-11-24_studio_portrait_edinburgh_0006.jpg",
        ];
        for (index, name) in names.iter().enumerate() {
            std::fs::copy(fixture.jpeg(name, [90, (60 * index) as u8, 200], 64, 96), root.join(name)).expect("copy");
        }
        engine.begin_scan(root.to_string_lossy().to_string()).expect("scan");
        for _ in 0..600 {
            if engine.poll().is_some() {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
        let ids: Vec<_> = engine
            .page(&Filter::default(), Sort::default(), 0, 100)
            .photos
            .iter()
            .map(|photo| photo.id)
            .collect();
        assert_eq!(ids.len(), 3, "three photographs");
        let mut thumbs = Thumbnails::new(dir.join("cache"));

        for width in [1440.0_f32, 1280.0, 1100.0, 980.0, 900.0] {
            let screen = vec2(width, 800.0);
            let mut state = UiState::new(ThemeKind::Charcoal, 0.0);
            state.view = View::Compare;
            state.selection.replace(ids[0]);
            state.compare = Some(ids[1]);
            let ctx = egui::Context::default();
            crate::theme::apply(&ctx, ThemeKind::Charcoal);
            crate::icons::install(&ctx);
            let mut output = ctx.run_ui(
                egui::RawInput {
                    screen_rect: Some(Rect::from_min_size(pos2(0.0, 0.0), screen)),
                    ..egui::RawInput::default()
                },
                |ctx| {
                    egui::CentralPanel::default().show(ctx, |ui| {
                        let _ = show(ui, &mut state, &mut engine, &mut thumbs);
                    });
                },
            );
            output.textures_delta.clear();
            let close = label_at(&output, "Close compare").expect("the compare row always offers a way out");
            let row = shapes_text(&output)
                .into_iter()
                .filter(|(_, rect)| rect.center().y > close.center().y - 8.0 && rect.center().y < close.center().y + 8.0)
                .collect::<Vec<_>>();
            // Room for the position on a wide canvas: the fix truncates, it does not drop the row.
            if width >= 1280.0 {
                assert!(row.iter().any(|(text, _)| text.contains(" of 3")), "the position is on the row");
            }
            // On a canvas too narrow for one row the names move above the buttons rather than
            // being ellipsized to a letter each: the row's widest name is still a real name, and it
            // sits clear of the button strip instead of running through it.
            let above = shapes_text(&output)
                .into_iter()
                .filter(|(_, rect)| rect.bottom() <= close.top() + 1.0 && rect.bottom() > close.top() - 30.0)
                .collect::<Vec<_>>();
            if width < 1100.0 {
                let widest = above.iter().map(|(_, rect)| rect.width()).fold(0.0_f32, f32::max);
                assert!(widest > 60.0, "the names get a row of their own at {width} (widest {widest})");
            }
            // And the degradation is asserted in both directions: the conveniences are offered on a
            // roomy canvas and gone on a narrow one, so a row that dropped them everywhere fails
            // as loudly as one that kept them where they do not fit.
            let every_text = shapes_text(&output).into_iter().map(|(text, _)| text).collect::<Vec<_>>();
            if width >= 1440.0 {
                assert!(
                    every_text.iter().any(|text| text == "Show in folder"),
                    "the conveniences are offered at {width}"
                );
            } else {
                assert!(
                    !every_text.iter().any(|text| text == "Show in folder"),
                    "the conveniences step aside at {width}"
                );
            }
            for (text, rect) in row {
                if rect.center().x < close.center().x {
                    assert!(
                        rect.max.x <= close.min.x + 0.5,
                        "at {width} points \"{text}\" ({rect:?}) runs into the button cluster, which starts at {}",
                        close.min.x
                    );
                }
            }
        }

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// Every text shape in the frame, in painting order.
    fn shapes_text(output: &egui::FullOutput) -> Vec<(String, Rect)> {
        fn walk(shape: &egui::Shape, out: &mut Vec<(String, Rect)>) {
            match shape {
                egui::Shape::Text(text) => out.push((text.galley.job.text.clone(), text.visual_bounding_rect())),
                egui::Shape::Vec(shapes) => {
                    for shape in shapes {
                        walk(shape, out);
                    }
                }
                _ => {}
            }
        }
        let mut out = Vec::new();
        for clipped in &output.shapes {
            walk(&clipped.shape, &mut out);
        }
        out
    }

    /// Where a label with this text was painted, and the clip it was painted inside.
    fn label_at_clip(output: &egui::FullOutput, needle: &str) -> Option<(Rect, Rect)> {
        fn walk(shape: &egui::Shape, needle: &str) -> Option<Rect> {
            match shape {
                egui::Shape::Text(text) if text.galley.job.text.contains(needle) => Some(text.visual_bounding_rect()),
                egui::Shape::Vec(shapes) => shapes.iter().find_map(|shape| walk(shape, needle)),
                _ => None,
            }
        }
        output
            .shapes
            .iter()
            .find_map(|clipped| walk(&clipped.shape, needle).map(|rect| (rect, clipped.clip_rect)))
    }

    /// Press and release at a point, painting the bar in between.
    fn click_frames(
        ctx: &egui::Context,
        screen: Vec2,
        at: egui::Pos2,
        state: &mut UiState,
        engine: &mut Engine,
        actions: &mut Vec<Action>,
    ) {
        let tokens = Tokens::CHARCOAL;
        for input in press_and_release(at) {
            let mut output = ctx.run_ui(
                egui::RawInput {
                    events: input.events,
                    screen_rect: Some(Rect::from_min_size(pos2(0.0, 0.0), screen)),
                    ..egui::RawInput::default()
                },
                |ctx| {
                    egui::CentralPanel::default().show(ctx, |ui| {
                        bottom_bar(ui, state, &tokens, engine, actions);
                    });
                },
            );
            output.textures_delta.clear();
        }
    }

    /// A key press and release, painting the whole shell in between: the keyboard's counterpart to
    /// [`click_shell`].
    fn key_shell(
        ctx: &egui::Context,
        screen: Vec2,
        key: Key,
        state: &mut UiState,
        engine: &mut Engine,
        thumbs: &mut Thumbnails,
        actions: &mut Vec<Action>,
    ) {
        let event = |pressed| egui::Event::Key {
            key,
            physical_key: None,
            pressed,
            repeat: false,
            modifiers: Modifiers::NONE,
        };
        for events in [vec![event(true)], vec![event(false)]] {
            let mut output = ctx.run_ui(
                egui::RawInput {
                    events,
                    screen_rect: Some(Rect::from_min_size(pos2(0.0, 0.0), screen)),
                    ..egui::RawInput::default()
                },
                |ctx| {
                    egui::CentralPanel::default().show(ctx, |ui| {
                        let asked = show(ui, state, engine, thumbs);
                        actions.extend(asked);
                    });
                },
            );
            output.textures_delta.clear();
        }
    }

    /// The Keyboard shortcuts overlay has always promised "Esc Close the dialog", and only the
    /// overlay itself kept the promise. A stack of dialogs now unwinds one press at a time, from the
    /// one painted last, which is the one the reader is looking at.
    #[test]
    fn escape_dismisses_the_front_most_dialog_one_press_at_a_time() {
        let dir = std::env::temp_dir().join(format!("sortlens-ui-escape-dialog-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let mut engine = Engine::open(&dir).expect("open a library");
        let mut state = UiState::new(ThemeKind::Charcoal, 0.0);
        let mut thumbs = Thumbnails::new(dir.join("cache"));
        let mut actions: Vec<Action> = Vec::new();
        let ctx = egui::Context::default();
        crate::icons::install(&ctx);
        let screen = vec2(1280.0, 800.0);

        state.history_open = true;
        state.health_open = true;
        state.export_open = true;
        let painted = paint_shell(&ctx, screen, &mut state, &mut engine, &mut thumbs, &mut actions);
        assert!(label_at(&painted, "Recent changes").is_some(), "the bottom of the stack is drawn");
        assert!(label_at(&painted, "Export").is_some(), "and the top");

        // Export is painted last, so it is the first to go.
        key_shell(&ctx, screen, Key::Escape, &mut state, &mut engine, &mut thumbs, &mut actions);
        assert!(!state.export_open, "the front-most window closed");
        assert!(state.health_open && state.history_open, "one press, one window");

        let painted = paint_shell(&ctx, screen, &mut state, &mut engine, &mut thumbs, &mut actions);
        assert!(label_at(&painted, "Library health").is_some(), "the next one is still there");
        // Recent changes was painted above Library health, so it goes next.
        key_shell(&ctx, screen, Key::Escape, &mut state, &mut engine, &mut thumbs, &mut actions);
        assert!(!state.history_open, "the window painted above the health one");
        assert!(state.health_open, "leaving the one behind it untouched");

        key_shell(&ctx, screen, Key::Escape, &mut state, &mut engine, &mut thumbs, &mut actions);
        assert!(!state.health_open, "and the last one");

        // Nothing left to dismiss: Escape now belongs to the view behind, which first drops the
        // selection, so a press with no dialog open is not swallowed by this list.
        state.selection.all(&[PhotoId(1)]);
        key_shell(&ctx, screen, Key::Escape, &mut state, &mut engine, &mut thumbs, &mut actions);
        assert!(state.selection.is_empty(), "the view still receives Escape");

        let _ = std::fs::remove_dir_all(&dir);
    }
    /// Phase 3B.4: a narrow window collapses the tab row into the current destination plus a menu, and the
    /// menu still holds every destination. Width is lost, not reach.
    #[test]
    fn a_narrow_window_collapses_the_tab_row_instead_of_dropping_a_destination() {
        // The threshold itself: the tabs plus the pill and the right-hand controls.
        assert!(tabs_collapse(820.0, 732.0), "a narrow bar collapses");
        assert!(!tabs_collapse(1440.0, 732.0), "a wide one does not");
        assert_eq!(View::ALL.len(), 9, "every destination is in the row");
        assert_eq!(View::ALL[0], View::Library, "the row starts where it always did");

        let dir = std::env::temp_dir().join(format!("sortlens-ui-collapse-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let mut engine = Engine::open(&dir).expect("open a library");
        let mut state = UiState::new(ThemeKind::Charcoal, 0.0);
        let mut actions: Vec<Action> = Vec::new();
        let ctx = egui::Context::default();
        crate::icons::install(&ctx);

        let wide = paint_bar(&ctx, vec2(1440.0, 300.0), &mut state, &mut engine, &mut actions);
        assert!(
            label_at(&wide, "Soft Focus").is_some(),
            "the wide row shows the last-but-one destination"
        );
        assert!(label_at(&wide, "Insights").is_some(), "and the last");

        let narrow = paint_bar(&ctx, vec2(820.0, 300.0), &mut state, &mut engine, &mut actions);
        assert!(
            label_at(&narrow, "Soft Focus").is_none(),
            "the collapsed row is the current destination, not the whole list"
        );
        let current = label_at(&narrow, "Library").expect("the current destination is named");
        click_frames(&ctx, vec2(820.0, 300.0), current.center(), &mut state, &mut engine, &mut actions);
        let opened = paint_bar(&ctx, vec2(820.0, 300.0), &mut state, &mut engine, &mut actions);
        assert!(
            label_at(&opened, "Soft Focus").is_some(),
            "the menu behind the collapsed tab still holds every destination"
        );
        assert!(actions.is_empty(), "opening the menu asks for nothing");

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// The bottom bar's destinations speak the interface language (SL-L07).
    ///
    /// `View::label()` stays the English source of truth; [`view_word`] looks its catalogue row up, so
    /// the tab row, the collapsed menu and the canvas header that repeats the name are one word in one
    /// language. A destination added later cannot arrive English-only: the row audit below fails for it
    /// in both catalogues before a frame is painted.
    #[test]
    fn the_bottom_bar_destinations_speak_the_interface_language() {
        for code in ["ar", "ja"] {
            let lang = crate::i18n::from_code(code).expect("the language is offered");
            for view in View::ALL {
                assert_ne!(
                    crate::i18n::I18N.t(lang, view.label()),
                    view.label(),
                    "{code} has no row for the {} destination",
                    view.label()
                );
            }
        }

        let dir = std::env::temp_dir().join(format!("sortlens-ui-destinations-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let mut engine = Engine::open(&dir).expect("open a library");
        let mut state = UiState::new(ThemeKind::Charcoal, 0.0);
        let mut actions: Vec<Action> = Vec::new();
        let ctx = egui::Context::default();
        crate::icons::install(&ctx);

        // English is unchanged, which is why no committed scene moved.
        let english = paint_bar(&ctx, vec2(1440.0, 300.0), &mut state, &mut engine, &mut actions);
        for view in View::ALL {
            assert!(label_at(&english, view.label()).is_some(), "{} is named in English", view.label());
        }

        // Every destination in each catalogue's own words, with no English left behind.
        for (code, words) in [
            (
                "ja",
                [
                    "ライブラリ",
                    "あなたへ",
                    "選別",
                    "詳細",
                    "比較",
                    "場所",
                    "インサイト",
                    "ソフトフォーカス",
                    "類似",
                ],
            ),
            (
                "ar",
                [
                    "المكتبة",
                    "لك",
                    "الفرز",
                    "تفاصيل",
                    "المقارنة",
                    "الأماكن",
                    "رؤى",
                    "تركيز ناعم",
                    "مشابهة",
                ],
            ),
        ] {
            crate::i18n::set_current(crate::i18n::from_code(code).expect("the language is offered"));
            // Wide enough that every destination keeps its tab in either script; the collapse itself
            // is the next assertion's subject, not this one's.
            let bar = paint_bar(&ctx, vec2(1600.0, 300.0), &mut state, &mut engine, &mut actions);
            for (view, word) in View::ALL.iter().zip(words) {
                assert!(
                    label_at(&bar, word).is_some(),
                    "{code}: {word} is not painted in place of {}",
                    view.label()
                );
                assert!(
                    label_at(&bar, view.label()).is_none(),
                    "{code} keeps the English destination {}: {words:?}",
                    view.label()
                );
            }
        }

        // A narrow bar loses width, not language: the collapsed tab is the current destination's own
        // word, and the menu behind it still names every destination.
        crate::i18n::set_current(crate::i18n::from_code("ja").expect("Japanese is offered"));
        state.view = View::Library;
        let narrow = paint_bar(&ctx, vec2(820.0, 300.0), &mut state, &mut engine, &mut actions);
        assert!(
            label_at(&narrow, "ライブラリ").is_some(),
            "the collapsed tab is the current destination"
        );
        assert!(label_at(&narrow, "ソフトフォーカス").is_none(), "and not the whole row");
        let current = label_at(&narrow, "ライブラリ").expect("the current destination is named");
        click_frames(&ctx, vec2(820.0, 300.0), current.center(), &mut state, &mut engine, &mut actions);
        let opened = paint_bar(&ctx, vec2(820.0, 300.0), &mut state, &mut engine, &mut actions);
        for word in ["あなたへ", "選別", "詳細", "比較", "場所", "インサイト", "ソフトフォーカス", "類似"] {
            assert!(label_at(&opened, word).is_some(), "the menu holds {word}");
        }

        // The canvas header repeats the word from the same row: one at the top of the canvas, one at the
        // foot of the window, and not a Latin letter between them.
        state.view = View::Detail;
        state.left_open = false;
        state.right_open = false;
        let mut thumbs = Thumbnails::new(dir.join("cache"));
        let japanese = paint_shell(&ctx, vec2(1280.0, 800.0), &mut state, &mut engine, &mut thumbs, &mut actions);
        let header = word_rects(&japanese, "詳細");
        assert!(
            header.iter().any(|rect| rect.center().y < 150.0),
            "the header names the view in Japanese: {header:?}"
        );
        assert!(
            header.iter().any(|rect| rect.center().y > 600.0),
            "and the bar does too: {header:?}"
        );
        assert!(label_at(&japanese, "Detail").is_none(), "no English header behind it");

        crate::i18n::set_current(crate::i18n::from_code("en").expect("English is offered"));
        let english = paint_shell(&ctx, vec2(1280.0, 800.0), &mut state, &mut engine, &mut thumbs, &mut actions);
        assert!(
            word_rects(&english, "Detail").iter().any(|rect| rect.center().y < 150.0),
            "English still names it in the header"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// Paint the whole shell, settled: the SVG loader is asynchronous, so one frame can be a frame with no glyphs.
    fn paint_shell(
        ctx: &egui::Context,
        screen: Vec2,
        state: &mut UiState,
        engine: &mut Engine,
        thumbs: &mut Thumbnails,
        actions: &mut Vec<Action>,
    ) -> egui::FullOutput {
        let input = egui::RawInput {
            screen_rect: Some(Rect::from_min_size(pos2(0.0, 0.0), screen)),
            ..egui::RawInput::default()
        };
        let mut settled = None;
        for _ in 0..3 {
            let mut output = ctx.run_ui(input.clone(), |ctx| {
                egui::CentralPanel::default().show(ctx, |ui| {
                    let asked = show(ui, state, engine, thumbs);
                    actions.extend(asked);
                });
            });
            output.textures_delta.clear();
            settled = Some(output);
        }
        settled.expect("three frames were painted")
    }

    /// A click anywhere in the shell: press in one frame, release in the next, painting the whole window.
    fn click_shell(
        ctx: &egui::Context,
        screen: Vec2,
        at: egui::Pos2,
        state: &mut UiState,
        engine: &mut Engine,
        thumbs: &mut Thumbnails,
        actions: &mut Vec<Action>,
    ) {
        for input in press_and_release(at) {
            let mut output = ctx.run_ui(
                egui::RawInput {
                    events: input.events,
                    screen_rect: Some(Rect::from_min_size(pos2(0.0, 0.0), screen)),
                    ..egui::RawInput::default()
                },
                |ctx| {
                    egui::CentralPanel::default().show(ctx, |ui| {
                        let asked = show(ui, state, engine, thumbs);
                        actions.extend(asked);
                    });
                },
            );
            output.textures_delta.clear();
        }
    }

    /// The glyphs painted inside `area`, top to bottom: the far-edge rail is a column, so its order is its y.
    fn glyphs_top_to_bottom(output: &egui::FullOutput, area: Rect) -> Vec<Rect> {
        let mut rects: Vec<Rect> = output
            .shapes
            .iter()
            .filter_map(|clipped| match &clipped.shape {
                egui::Shape::Mesh(mesh) => Some(mesh.calc_bounds()),
                egui::Shape::Rect(shape) => shape
                    .brush
                    .as_ref()
                    .filter(|brush| brush.fill_texture_id != egui::TextureId::default())
                    .map(|_| shape.rect),
                _ => None,
            })
            .filter(|rect| area.contains(rect.center()))
            .collect();
        rects.sort_by(|left, right| left.center().y.total_cmp(&right.center().y));
        rects
    }

    /// Phase 3B.5: the four questions live on a far-edge rail that is always there, and switching tools never closes
    /// the panel — that is the whole point of the pattern.
    #[test]
    fn the_far_edge_rail_switches_the_panel_and_only_a_second_click_closes_it() {
        assert_eq!(RightTab::ALL.len(), 4, "four questions, in tab order");
        assert_eq!(
            RightTab::ALL[2],
            RightTab::Suggestions,
            "Suggestions sits between Tags and Activity"
        );
        assert_eq!(RightTab::ALL[3], RightTab::Activity, "and Activity stays last");

        let dir = std::env::temp_dir().join(format!("sortlens-ui-right-rail-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let mut engine = Engine::open(&dir).expect("open a library");
        let mut state = UiState::new(ThemeKind::Charcoal, 0.0);
        let mut thumbs = Thumbnails::new(dir.join("cache"));
        let mut actions: Vec<Action> = Vec::new();
        let ctx = egui::Context::default();
        let screen = vec2(1200.0, 800.0);
        // The rail spans the window between the top and bottom bars, so the band is clipped to that middle: the top
        // bar's own glyphs sit at the same x and would otherwise be counted as rail entries.
        let rail = Rect::from_min_max(pos2(screen.x - TAB_STRIP_W, 50.0), pos2(screen.x, screen.y - 60.0));

        let painted = paint_shell(&ctx, screen, &mut state, &mut engine, &mut thumbs, &mut actions);
        let glyphs = glyphs_top_to_bottom(&painted, rail);
        assert_eq!(
            glyphs.len(),
            RightTab::ALL.len(),
            "one glyph per question and nothing else in the rail: {glyphs:?}"
        );
        assert_eq!(state.right_tab, RightTab::Details, "Details is still the first question");
        assert!(state.right_open);

        click_shell(&ctx, screen, glyphs[2].center(), &mut state, &mut engine, &mut thumbs, &mut actions);
        assert_eq!(state.right_tab, RightTab::Suggestions, "the third glyph is Suggestions");
        assert!(state.right_open, "switching tools keeps the panel open");
        let switched = paint_shell(&ctx, screen, &mut state, &mut engine, &mut thumbs, &mut actions);
        assert!(
            label_at(&switched, "Suggestions").is_some(),
            "the panel's header names the tool it is showing"
        );

        let glyphs = glyphs_top_to_bottom(&switched, rail);
        click_shell(&ctx, screen, glyphs[1].center(), &mut state, &mut engine, &mut thumbs, &mut actions);
        assert_eq!(state.right_tab, RightTab::Tags);
        assert!(state.right_open, "moving between tools never hides the panel");

        let tags = paint_shell(&ctx, screen, &mut state, &mut engine, &mut thumbs, &mut actions);
        let glyphs = glyphs_top_to_bottom(&tags, rail);
        click_shell(&ctx, screen, glyphs[1].center(), &mut state, &mut engine, &mut thumbs, &mut actions);
        assert!(!state.right_open, "clicking the active tool closes the body");
        assert_eq!(state.right_tab, RightTab::Tags, "and remembers which tool it was");

        let closed = paint_shell(&ctx, screen, &mut state, &mut engine, &mut thumbs, &mut actions);
        assert_eq!(
            glyphs_top_to_bottom(&closed, rail).len(),
            RightTab::ALL.len(),
            "the rail is still there with the body closed, which is how the body is reopened"
        );
        assert!(actions.is_empty(), "none of this asks the host for anything");
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// A phone is narrower than both docks and narrower than the wordmark's words.
    ///
    /// A window that opens at that width opens on the grid: both docks put away, one glyph each in the bar to bring
    /// them back, and nothing painted off the side of the screen. Every screenshot baseline starts at 900 points, so
    /// this is the only place the narrow layout is asked to hold together.
    /// The phone canvas is the point of the phone: at 390 points the chrome — the canvas header, the
    /// filter strip and the bottom bar's tray — is compact enough that the grid gets the room, and
    /// nothing the canvas paints runs off the screen. Phase 4 item 3b's remaining half.
    #[test]
    fn a_phone_canvas_spends_its_room_on_the_grid() {
        let dir = std::env::temp_dir().join(format!("sortlens-ui-phone-canvas-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let root = dir.join("Photos");
        std::fs::create_dir_all(&root).expect("root");
        let fixture = sortlens_testkit::Fixture::new("ui-phone-canvas");
        for index in 0..6 {
            let name = format!("IMG_{index}.jpg");
            std::fs::copy(fixture.jpeg(&name, [20 + index * 30, 90, 170], 64, 48), root.join(&name)).expect("copy");
        }
        let mut engine = Engine::open(&dir).expect("open a library");
        engine.begin_scan(root.to_string_lossy().to_string()).expect("scan");
        for _ in 0..600 {
            if engine.poll().is_some() {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
        assert_eq!(engine.stats().total, 6, "the canvas needs photographs to make room for");
        let mut thumbs = Thumbnails::new(dir.join("cache"));
        let mut actions: Vec<Action> = Vec::new();
        let ctx = egui::Context::default();
        crate::icons::install(&ctx);
        let phone = vec2(390.0, 780.0);
        let t = Tokens::CHARCOAL;
        let mut state = UiState::new(ThemeKind::Charcoal, 0.0);
        let painted = paint_shell(&ctx, phone, &mut state, &mut engine, &mut thumbs, &mut actions);
        assert!(state.narrow, "390 points is a phone");
        assert!(state.filters_open, "the strip is open, which is where the rows are counted");
        assert!(engine.stats().total > 0, "the strip needs a library");

        // The far-edge rail stands down while the inspector is put away: four 14-point glyphs in a
        // 30-point column were a tenth of the screen spent on a tool the bar's own inspector glyph
        // offers. What is painted in the band above the grid is the shell's chrome, and none of it
        // may sit in the rail's old column.
        let band_top = t.top_bar_h;
        let rail: Vec<Rect> = painted_pictures(&painted)
            .into_iter()
            .filter(|rect| rect.center().y > band_top && rect.center().y < band_top + 100.0 && rect.center().x > phone.x - TAB_STRIP_W)
            .collect();
        assert!(
            rail.is_empty(),
            "the far-edge rail is painted beside a closed panel at {} points: {rail:?}",
            phone.x
        );
        // And the canvas uses the room: the strip's card spans the full canvas width, which the
        // rail's 30 points used to keep it from, and its bottom edge is where the grid starts. Two
        // chip rows put the first photograph at about 150 points instead of the ~190 the desktop
        // chrome spent.
        let cards: Vec<Rect> = all_shapes(&painted)
            .into_iter()
            .filter_map(|shape| match shape {
                egui::Shape::Rect(rect) if rect.fill == t.card => Some(rect.rect),
                _ => None,
            })
            .filter(|rect| rect.top() > band_top && rect.bottom() < 200.0)
            .collect();
        let card = cards
            .iter()
            .max_by(|a, b| a.width().total_cmp(&b.width()))
            .copied()
            .expect("the strip's card is painted");

        assert!(
            card.right() >= phone.x - 20.0,
            "the strip ends at {}, short of the room the rail gave back",
            card.right()
        );
        assert!(
            card.bottom() <= 152.0,
            "the chrome before the grid ends at {}, still a layer deep",
            card.bottom()
        );

        // The strip is two rows of chips on a phone, and it keeps no count: the canvas header's count
        // is the same number on the same screen. Grouped by row, the eight chip words must be two
        // rows — three is the desktop's wrap with a count column the phone does not have.
        let chip_labels = ["+ keyword", "Rating", "Flags", "Colour", "All kinds", "Source", "Edited", "Missing"];
        let mut chips: Vec<Rect> = chip_labels.iter().filter_map(|label| label_at(&painted, label)).collect();
        assert_eq!(chips.len(), chip_labels.len(), "every chip is painted at phone width");
        assert!(
            label_at(&painted, "shown").is_none(),
            "a second count sits under the header's own at phone width"
        );
        chips.sort_by(|a, b| a.center().y.total_cmp(&b.center().y));
        let rows: Vec<f32> = {
            let mut rows: Vec<f32> = Vec::new();
            for rect in &chips {
                let y = rect.center().y;
                if rows.last().is_none_or(|last| (y - last).abs() > 6.0) {
                    rows.push(y);
                }
            }
            rows
        };
        assert_eq!(rows.len(), 2, "the strip wraps to {rows:?} rows of chips at 390 points");

        // The bottom bar's tray fits: every picture it paints is on the screen, which the desktop pill
        // broke by thirty points at 390 — the last flag button was half off the edge and could not be
        // tapped.
        let bar_top = phone.y - t.bottom_bar_h;
        let tray: Vec<Rect> = painted_pictures(&painted)
            .into_iter()
            .filter(|rect| rect.top() >= bar_top)
            .chain(
                shapes_text(&painted)
                    .into_iter()
                    .map(|(_, rect)| rect)
                    .filter(|rect| rect.top() >= bar_top),
            )
            .collect();
        assert!(!tray.is_empty(), "the tray painted something to measure");
        for rect in tray {
            assert!(
                rect.right() <= phone.x + 0.5,
                "a bottom-bar control is clipped at {rect:?} in a {}-point window",
                phone.x
            );
        }

        // And the header keeps everything it has: name, count, sort and the two grid glyphs, all on
        // the screen.
        assert!(label_at(&painted, "Library").is_some(), "the view's name");
        assert!(label_at(&painted, "6 photos").is_some(), "the canvas's one count");
        assert!(label_at(&painted, "Added order").is_some(), "the sort combo");
        let header_glyphs = painted_pictures(&painted)
            .into_iter()
            .filter(|rect| rect.center().y > t.top_bar_h && rect.center().y < t.top_bar_h + 40.0 && rect.left() < phone.x - TAB_STRIP_W)
            .count();
        assert!(header_glyphs >= 2, "the density and layout glyphs are still in the header");
        assert!(actions.is_empty(), "painting the phone canvas asks the host for nothing");
        let _ = std::fs::remove_dir_all(&dir);
    }

